        public Edit(int expectedVersion,String tradeTimeRaw,String amountRaw,String direction,String currency,String balanceRaw,String counterAccount,String counterparty,String transactionRef,String summary,String reviewStatus,Boolean included,String reason){this(expectedVersion,tradeTimeRaw,amountRaw,direction,currency,balanceRaw,counterAccount,counterparty,transactionRef,summary,reviewStatus,included,reason,null);}
